  [T.BRICK]: '#4a4f4a', [T.SNOW]: '#c3d3dc', [T.ICE]: '#8fc5d6', [T.CAVE]: '#262536',
  [T.CRYSTAL_FLOOR]: '#2c3f4a', [T.PAVE]: '#68604e', [T.WOOD]: '#5d452f', [T.ROCK]: '#343b3a',
  [T.SNOWROCK]: '#7a8a92', [T.CAVEWALL]: '#191826', [T.MOSS]: '#3d4a38', [T.SNOWPATH]: '#a8b8c2',
};

