738: /* ---------------- collision queries ---------------- */
739: export function collidesStatic(m, x, y, r = 5) {
740:   const tx = Math.floor(x / TILE), ty = Math.floor(y / TILE);
741:   for (let oy = -1; oy <= 1; oy++) for (let ox = -1; ox <= 1; ox++) {
742:     const nx = tx + ox, ny = ty + oy;
743:     if (nx < 0 || ny < 0 || nx >= m.w || ny >= m.h) return true;
744:     if (m.solid[ny * m.w + nx]) return true;
745:   }
746:   const cx = Math.floor(x / 64), cy = Math.floor(y / 64);
747:   for (let gy = cy - 1; gy <= cy + 1; gy++) for (let gx = cx - 1; gx <= cx + 1; gx++) {
748:     const k = gx + ',' + gy;
749:     const cs = m.gridCircles.get(k);
750:     if (cs) for (const c of cs) {
751:       const dx = x - c.x, dy = y - c.y;
752:       if (dx * dx + dy * dy < (c.r + r) * (c.r + r)) return true;
753:     }
754:     const rs = m.gridRects.get(k);
755:     if (rs) for (const c of rs) {
756:       if (x + r > c.x && x - r < c.x + c.w && y + r * 0.5 > c.y && y - r * 0.5 < c.y + c.h) return true;
757:     }
758:   }
759:   return false;
760: }
