77: export function makeEquipment(level = 1, rarity = null, forceKind = null, rarityBias = 0) {
78:   if (!rarity) rarity = pickRarity(rarityBias);
79:   const kind = forceKind || ['weapon', 'weapon', 'armor', 'charm'][(Math.random() * 4) | 0];
80:   let base;
81:   if (kind === 'weapon') {
82:     const pool = WEAPONS.filter(w => w.tier <= Math.max(1, Math.floor(level / 2.5) + 1));
83:     base = pool[(Math.random() * pool.length) | 0] || WEAPONS[0];
84:   } else if (kind === 'armor') {
85:     const pool = ARMORS.filter(w => w.tier <= Math.max(1, Math.floor(level / 2.5) + 1));
86:     base = pool[(Math.random() * pool.length) | 0] || ARMORS[0];
87:   } else {
88:     const pool = CHARMS.filter(w => w.tier <= Math.max(1, Math.floor(level / 2.2) + 1));
89:     base = pool[(Math.random() * pool.length) | 0] || CHARMS[0];
90:   }
91:   const mult = RARITY[rarity].mult;
92:   const stats = {};
93:   const scale = 1 + (level - 1) * 0.16;
94:   if (base.atk) stats.atk = Math.round(base.atk * scale * mult * 0.85 + (mult - 1) * 2);
95:   if (base.def) stats.def = Math.round(base.def * scale * mult * 0.8);
96:   if (base.hp) stats.hp = Math.round(base.hp * scale * mult);
97:   if (base.energy) stats.energy = Math.round(base.energy * scale * mult * 0.8);
98:   if (base.crit) stats.crit = Math.round(base.crit * mult * 0.8);
99:   if (base.speed) stats.speed = Math.round(base.speed);
100:   if (base.regen) stats.regen = base.regen;
101:   if (base.lifesteal) stats.lifesteal = base.lifesteal;
102:   // rarity random affix
103:   const affix = ['hp', 'energy', 'crit', 'speed', 'def', 'atk'][(Math.random() * 6) | 0];
104:   const affixVal = Math.ceil(2 + level * 0.4 * mult);
105:   const idx = RARITY_ORDER.indexOf(rarity);
106:   if (idx >= 1 && !stats[affix]) stats[affix] = affixVal;
107:   let name = base.name;
108:   if (rarity !== 'common' && Math.random() < 0.6) {
109:     const pre = PREFIXES[rarity] ? PREFIXES[rarity][(Math.random() * PREFIXES[rarity].length) | 0] : null;
110:     if (pre && !name.includes(pre)) name = pre + ' ' + name;
111:   }
112:   if ((rarity === 'epic' || rarity === 'legendary') && Math.random() < 0.5) {
113:     const suf = SUFFIXES[rarity][(Math.random() * SUFFIXES[rarity].length) | 0];
114:     name = name + ' ' + suf;
115:   }
116:   const slot = kind === 'armor' ? 'armor' : kind === 'charm' ? 'charm' : 'weapon';
117:   return {
118:     uid: nextItemUID(),
119:     baseId: base.id,
120:     name, type: slot, kind: base.kind, icon: base.icon,
121:     rarity, level, stats,
122:     slow: !!base.slow,
123:     desc: base.desc,
124:     value: Math.round((8 + level * 5) * mult * (slot === 'weapon' ? 1.2 : 1)),
125:     category: 'equipment',
126:     iconUrl: getItemIcon(base.icon, RARITY[rarity].color),
127:   };
128: }
