592:   playerMelee(heavy, combo) {
593:     const p = this.player;
594:     const range = heavy ? 50 : 40;
595:     const arc = heavy ? 2.6 : 1.9;
596:     const baseMult = heavy ? 2.2 : [1, 1.08, 1.5][combo] || 1;
597:     let hits = 0;
598:     const targets = [...this.enemies];
599:     for (const e of targets) {
600:       if (e.dead || e.spawnBlink > 0) continue;
601:       const d = dist(p, e);
602:       if (d > range + e.r + 6) continue;
603:       const a = angleTo(p.x, p.y, e.x, e.y);
604:       let diff = Math.abs(((a - p.aimAngle + Math.PI * 3) % TAU) - Math.PI);
605:       if (diff > arc / 2 && d > 18) continue;
606:       const crit = chance(p.crit / 100);
607:       let dmg = p.atk * baseMult * (heavy ? p.heavyDmgMult : 1) * (crit ? 1.8 : 1);
608:       if (e.armored && !heavy) dmg *= .68;
609:       dmg = e.hurt(dmg, { from: p, source: 'melee', heavy });
610:       this.showHit(e, dmg, crit, hugeColor(heavy, crit));
611:       hits++;
612:       if (p.lifesteal > 0) p.heal(p.lifesteal * dmg);
613:       this.burst(e.x, e.y - 12, heavy ? 12 : 6, heavy ? '#ffe0a8' : '#dffcf5', { speed: heavy ? 110 : 75, life: .35, size: 1.8, glow: true });
614:       if (heavy) e.stun(.55);
615:     }
616:     // interactive training dummies? none
617:     if (hits) {
618:       this.audio.sfx('hit');
619:       this.shake(heavy ? 7 : 2.6);
620:       this.hitStop = heavy ? .055 : .02;
621:     } else this.shake(heavy ? 2 : .5);
622:   }
