624:   showHit(e, dmg, crit, color) {
625:     this.addDamageNumber(e.x + rand(-6, 6), e.y - (e.r * 1.9) - 8, `${crit ? '✧' : ''}${Math.round(dmg)}`, crit ? '#ffe6a8' : color || '#f4e7d0', crit, crit || dmg > 40);
626:     if (crit) this.audio.sfx('crit'); else this.audio.sfx('hit');
627:   }
