629:   useAbility(id) {
630:     const p = this.player;
631:     if (!this.playerCanAct()) return false;
632:     const ab = ABILITIES[id];
633:     if (!ab || !p.abilities[id]) { this.ui.toast('Ability not yet awakened', 'bad'); return false; }
634:     if (this.paused || this.dialogueOpen) return false;
635:     if (p.cooldowns[id] > 0) { this.audio.sfx('error'); return false; }
636:     if (p.dodge || p.attack || p.castTimer > 0) return false;
637:     const cost = Math.round(ab.cost * p.abilityCostMult);
638:     if (p.energy < cost) { this.ui.toast('Not enough energy', 'bad'); this.audio.sfx('error'); return false; }
639:     p.spendEnergy(cost);
640:     let cd = ab.cd;
641:     if (id === 'blink') cd *= 1 + this.skillEffect('blinkCd');
642:     p.cooldowns[id] = cd;
643:     p.startCast(id === 'echo' ? .48 : .3);
644:     this.audio.sfx('cast');
645:     const ang = p.aimAngle;
646:     const dmgMult = p.abilityDmgMult;
647:     if (id === 'burst') {
648:       const dmg = (ab.damage + p.atk * .9) * dmgMult * (1 + this.skillEffect('burstDmg'));
649:       const pierce = (ab.pierce || 0) + this.skillEffect('burstPierce');
650:       this.projectiles.push(new Projectile(this, {
651:         x: p.x + Math.cos(ang) * 18, y: p.y - 10 + Math.sin(ang) * 14,
652:         angle: ang, speed: ab.speed, dmg, friendly: true, r: 7, pierce,
653:         color: ab.color, kind: 'burst', life: 1.1, owner: p,
654:       }));
655:       this.burst(p.x + Math.cos(ang) * 18, p.y - 10 + Math.sin(ang) * 14, 7, ab.color, { speed: 45, life: .3, size: 2, glow: true });
656:       this.audio.sfx('orb');
657:     } else if (id === 'blink') {
658:       const maxD = ab.distance;
659:       let tx = p.x, ty = p.y;
660:       for (let s = 8; s <= maxD; s += 8) {
661:         const nx = p.x + Math.cos(ang) * s, ny = p.y + Math.sin(ang) * s;
662:         if (this.collides(nx, ny, p.r)) break;
663:         tx = nx; ty = ny;
664:       }
665:       this.effects.push({ type: 'afterimage', x: p.x, y: p.y, t: 0, max: .5, dir: p.facing, flip: p.flip, outfit: p.outfit, accessory: p.accessory });
666:       p.x = tx; p.y = ty; p.invuln = Math.max(p.invuln, .55);
667:       this.effects.push({ type: 'ring', x: tx, y: ty - 8, t: 0, max: .55, color: ab.color, radius: 44 });
668:       this.burst(tx, ty - 8, 14, ab.color, { speed: 95, life: .5, size: 2, glow: true });
669:       this.audio.sfx('blink');
670:     } else if (id === 'nova') {
671:       const dmg = (ab.damage + p.atk * 1.2) * dmgMult;
672:       this.aoeDamage(p.x, p.y, ab.radius, dmg, { knockback: 240, color: ab.color, stun: .45 });
673:       this.effects.push({ type: 'ring', x: p.x, y: p.y - 6, t: 0, max: .55, color: ab.color, radius: ab.radius, thick: true });
674:       this.burst(p.x, p.y - 6, 30, ab.color, { speed: 170, life: .65, size: 2.6, glow: true });
675:       this.shake(9);
676:       this.audio.sfx('nova');
677:     } else if (id === 'frost') {
678:       const dmg = (ab.damage + p.atk * .8) * dmgMult;
679:       this.aoeDamage(p.x, p.y, ab.radius, dmg, { color: ab.color, slow: ab.slow || 4, stun: .2 });
680:       this.effects.push({ type: 'ring', x: p.x, y: p.y - 6, t: 0, max: .9, color: ab.color, radius: ab.radius, frost: true });
681:       this.burst(p.x, p.y - 6, 28, ab.color, { speed: 130, life: 1.1, size: 2.2, glow: true, gravity: -8 });
682:       this.audio.sfx('frost');
683:     } else if (id === 'echo') {
684:       const radius = ab.radius * (1 + this.skillEffect('echoRadius'));
685:       const dmg = (ab.damage + p.atk * 2) * dmgMult * (1 + this.skillEffect('echoDmg'));
686:       this.aoeDamage(p.x, p.y, radius, dmg, { knockback: 300, stun: 1.1, heavy: true });
687:       this.effects.push({ type: 'ring', x: p.x, y: p.y - 6, t: 0, max: 1, color: ab.color, radius, thick: true, echo: true });
688:       this.effects.push({ type: 'echoWave', x: p.x, y: p.y - 6, t: 0, max: 1.1, color: ab.color, radius });
689:       this.burst(p.x, p.y - 8, 50, ab.color, { speed: 220, life: 1.2, size: 3, glow: true });
690:       this.shake(16);
691:       this.audio.sfx('echo');
692:     }
693:     this.ui.refreshAbilities();
694:     return true;
695:   }
