697:   aoeDamage(x, y, radius, dmg, opts = {}) {
698:     for (const e of this.enemies) {
699:       if (e.dead) continue;
700:       const d = Math.hypot(e.x - x, e.y - y);
701:       if (d > radius + e.r) continue;
702:       const falloff = 1 - clamp((d - radius * .4) / radius, 0, .55);
703:       const crit = chance(this.player.crit / 100);
704:       const dealt = e.hurt(dmg * falloff * (crit ? 1.7 : 1), { from: this.player, source: 'ability', heavy: !!opts.heavy });
705:       this.showHit(e, dealt, crit, opts.color);
706:       if (e.knockX != null) {
707:         const a = angleTo(x, y, e.x, e.y);
708:         e.knockX = Math.cos(a) * (opts.knockback || 120);
709:         e.knockY = Math.sin(a) * (opts.knockback || 120);
710:       }
711:       if (opts.slow) e.slow(opts.slow, .5);
712:       if (opts.stun) e.stun(opts.stun);
713:     }
714:   }
