735:   updateZones(dt) {
736:     for (const z of this.zones) {
737:       z.t += dt;
738:       if (!z.hit && z.t >= z.warn) {
739:         z.hit = true;
740:         const p = this.player;
741:         let hit = false;
742:         if (z.type === 'line') {
743:           const dx = Math.cos(z.angle), dy = Math.sin(z.angle);
744:           const rx = p.x - z.x, ry = p.y - z.y;
745:           const proj = rx * dx + ry * dy;
746:           if (proj > -10 && proj < z.length) {
747:             const px0 = z.x + dx * proj, py0 = z.y + dy * proj;
748:             if (Math.hypot(p.x - px0, p.y - py0) < z.width / 2 + p.r) hit = true;
749:           }
750:         } else {
751:           if (Math.hypot(p.x - z.x, p.y - z.y) < z.r + p.r) hit = true;
752:         }
753:         if (hit) p.damage(z.dmg, { source: { x: z.x, y: z.y }, knockback: z.type === 'line' ? 180 : 120 });
754:         this.effects.push({ type: 'zoneBurst', x: z.x, y: z.y, t: 0, max: .5, color: z.color, r: z.r, angle: z.angle, length: z.length, width: z.width, line: z.type === 'line', root: z.root });
755:         this.burst(z.x, z.y, 14, z.color, { speed: 120, life: .6, size: 2.4, glow: true, gravity: z.root ? -50 : 0 });
756:         this.shake(4);
757:         this.audio.sfx(z.root ? 'seal' : 'hit');
758:       }
759:     }
760:     this.zones = this.zones.filter(z => z.t < z.warn + z.post);
761:   }
