56: function pickRarity(bias = 0) {
57:   const roll = Math.random() * 100;
58:   const boost = bias * 10;
59:   let acc = 0;
60:   const adjusted = {
61:     common: Math.max(8, 42 - boost * 2),
62:     uncommon: 28,
63:     rare: 18 + boost,
64:     epic: 9 + boost * 0.7,
65:     legendary: 3 + boost * 0.45,
66:   };
67:   const total = Object.values(adjusted).reduce((a, b) => a + b, 0);
68:   const target = roll / 100 * total;
69:   for (const r of RARITY_ORDER) { acc += adjusted[r]; if (target <= acc) return r; }
70:   return 'common';
71: }
