161: /* A named reward item, used by quests, shops and set loot. */
162: export function makeNamedEquipment(baseId, level = 3, rarity = 'rare') {
163:   const weapon = WEAPONS.find(w => w.id === baseId);
164:   const armor = ARMORS.find(a => a.id === baseId);
165:   const charm = CHARMS.find(c => c.id === baseId);
166:   const base = weapon || armor || charm;
167:   if (!base) return null;
168:   const slot = weapon ? 'weapon' : armor ? 'armor' : 'charm';
169:   const mult = RARITY[rarity] ? RARITY[rarity].mult : 1;
170:   const stats = {};
171:   for (const key of ['atk', 'def', 'hp', 'energy', 'crit', 'speed', 'regen', 'lifesteal']) {
172:     if (base[key]) stats[key] = base[key];
173:   }
174:   return {
175:     uid: nextItemUID(), baseId: base.id, name: base.name, type: slot,
176:     kind: base.kind, icon: base.icon, rarity, level, stats,
177:     slow: !!base.slow, desc: base.desc, category: 'equipment',
178:     value: Math.round((10 + level * 6) * mult),
179:     iconUrl: getItemIcon(base.icon, RARITY[rarity].color),
180:   };
181: }
