kbd{font-family:var(--sans);font-size:.72em;padding:.1em .42em;border:1px solid var(--line);border-bottom-width:2px;border-radius:3px;background:rgba(255,255,255,.06);color:var(--gold-2)}

/* ------- full-screen overlays ------- */
#vignette{position:absolute;inset:0;pointer-events:none;z-index:5;
  background:radial-gradient(ellipse at 50% 48%,transparent 52%,rgba(3,7,9,.34) 82%,rgba(2,5,7,.72) 100%);}
#grade{position:absolute;inset:0;pointer-events:none;z-index:4;mix-blend-mode:soft-light;opacity:.55;
  background:linear-gradient(160deg,rgba(90,150,140,.22),transparent 40%,rgba(190,140,70,.12) 70%,rgba(30,50,80,.25));}
#hurtFlash{position:absolute;inset:0;pointer-events:none;z-index:9;opacity:0;transition:opacity .18s;
  background:radial-gradient(ellipse at center,transparent 40%,rgba(150,20,30,.55) 100%)}
#hurtFlash.on{opacity:1;transition:none}
#fade{position:absolute;inset:0;pointer-events:none;z-index:60;background:#04070a;opacity:0;transition:opacity .55s ease}
#fade.on{opacity:1}

/* ------- HUD ------- */
#hud{position:absolute;inset:0;z-index:20;pointer-events:none}
#hud > *{pointer-events:none}

#minimapWrap{position:absolute;left:calc(18px + var(--safe-l));top:16px;width:166px;height:166px;
  border-radius:6px;background:rgba(6,11,14,.72);border:1px solid rgba(216,183,116,.32);
  box-shadow:0 8px 30px rgba(0,0,0,.45),inset 0 0 30px rgba(0,0,0,.5);
  padding:5px;overflow:hidden;backdrop-filter:blur(2px)}
#minimap{width:100%;height:100%;display:block;image-rendering:pixelated;border-radius:3px}
#regionLabel{position:absolute;left:7px;top:174px;font-family:var(--serif);font-size:12.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-2);text-shadow:0 2px 4px #000;white-space:nowrap}
#mapHint{position:absolute;right:2px;top:174px;font-size:10px;color:var(--muted);letter-spacing:.08em}
#minimapWrap::after{content:"";position:absolute;inset:4px;border:1px solid rgba(216,183,116,.13);border-radius:3px;pointer-events:none}

#objective{position:absolute;right:20px;top:18px;max-width:310px;text-align:right;padding:10px 14px 11px;
  background:linear-gradient(90deg,transparent,rgba(8,13,18,.72) 30%,rgba(8,13,18,.82));
  border-right:2px solid rgba(216,183,116,.55);border-radius:3px}
.obj-label{font-size:9.5px;letter-spacing:.22em;color:var(--gold);text-transform:uppercase;margin-bottom:5px;display:flex;gap:7px;justify-content:flex-end;align-items:center}
.diamond{width:6px;height:6px;background:var(--gold);transform:rotate(45deg);display:inline-block;box-shadow:0 0 6px rgba(216,183,116,.6)}
#objText{font-family:var(--serif);font-size:15px;line-height:1.4;color:#efe9d9;text-shadow:0 2px 6px #000}

#vitals{position:absolute;left:calc(20px + var(--safe-l));bottom:calc(20px + var(--safe-b));display:flex;gap:11px;align-items:flex-end}
#levelMedal{width:58px;height:58px;flex:0 0 auto;border-radius:50%;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;
  background:radial-gradient(circle at 35% 28%,#2a323c,#0b1015 72%);
  border:1px solid rgba(216,183,116,.65);box-shadow:0 0 0 3px rgba(6,10,14,.75),0 0 22px rgba(216,183,116,.15),inset 0 0 14px rgba(0,0,0,.8)}
#levelMedal::before{content:"";position:absolute;inset:4px;border-radius:50%;border:1px dashed rgba(216,183,116,.28)}
#levelNum{font-family:var(--serif);font-size:23px;line-height:1;color:var(--gold-2);text-shadow:0 0 10px rgba(216,183,116,.45)}
#levelMedal small{font-size:7px;letter-spacing:.16em;color:#9b8c68;margin-top:2px}
#barStack{width:min(300px,34vw);display:flex;flex-direction:column;gap:4px;padding-bottom:3px}
.bar{position:relative;height:15px;border-radius:2px;background:rgba(4,8,11,.82);border:1px solid rgba(0,0,0,.65);
  box-shadow:0 0 0 1px rgba(216,183,116,.13),inset 0 1px 3px rgba(0,0,0,.8);overflow:hidden}
.bar.energy{height:9px}
.bar.stam{height:6px}
.bar .fill{position:absolute;left:0;top:0;bottom:0;width:100%;transition:width .18s ease;border-radius:1px}
.bar.hp .fill{background:linear-gradient(180deg,#e08484,var(--hp) 45%,#7d2937);box-shadow:0 0 12px rgba(194,81,93,.5)}
.bar.energy .fill{background:linear-gradient(180deg,#93ddf1,var(--en) 50%,#21577a)}
.bar.stam .fill{background:linear-gradient(180deg,#c7e0a2,#7aa863 55%,#3f5b33)}
.bar-txt{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:9.5px;letter-spacing:.1em;color:rgba(255,250,240,.9);text-shadow:0 1px 2px #000,0 0 6px #000}
.bar.energy .bar-txt{font-size:8px;justify-content:flex-end;padding-right:6px;opacity:.85}
#xpTrack{height:3px;background:rgba(0,0,0,.65);border-radius:2px;margin-top:1px;overflow:hidden;position:relative}
#xpFill{display:block;height:100%;width:0;background:linear-gradient(90deg,#7a5f2d,var(--gold),#fff0c5);box-shadow:0 0 8px rgba(216,183,116,.7);transition:width .4s}

#abilities{position:absolute;left:50%;bottom:calc(16px + var(--safe-b));transform:translateX(-50%);display:flex;gap:9px;align-items:flex-end}
.ab-slot{width:46px;height:46px;position:relative;border-radius:6px;background:rgba(8,13,18,.88);
  border:1px solid rgba(216,183,116,.28);box-shadow:0 4px 14px rgba(0,0,0,.5),inset 0 0 12px rgba(0,0,0,.7);
  display:flex;align-items:center;justify-content:center;overflow:hidden;transition:transform .1s,border-color .2s}
.ab-slot .glyph{font-family:var(--serif);font-size:19px;color:#d8e8e4;text-shadow:0 0 9px rgba(111,217,200,.6);opacity:.95}
.ab-slot .key{position:absolute;left:3px;top:1px;font-size:8px;color:#a8976e;letter-spacing:.05em}
.ab-slot .cd{position:absolute;inset:0;background:rgba(2,6,9,.82);transform-origin:bottom;display:none}
.ab-slot.cooling .cd{display:block}
.ab-slot .cdtxt{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:12px;color:#cfe7e2;z-index:2}
.ab-slot.locked{opacity:.4}
.ab-slot.locked::after{content:"locked";position:absolute;bottom:2px;font-size:6px;letter-spacing:.12em;color:#7f8e92;text-transform:uppercase}
.ab-slot.noenergy{border-color:rgba(190,70,80,.5)}
.ab-slot.ready{box-shadow:0 0 0 1px rgba(111,217,200,.15),0 0 14px rgba(111,217,200,.08),inset 0 0 12px rgba(0,0,0,.7)}
.ab-slot .cost{position:absolute;right:3px;bottom:1px;font-size:7.5px;color:#7f9ca8}

#bossbar{position:absolute;left:50%;top:20px;transform:translateX(-50%);width:min(620px,64vw);text-align:center}
#bossName{font-family:var(--serif);font-size:19px;letter-spacing:.19em;text-transform:uppercase;color:#f0dfbc;text-shadow:0 2px 8px #000,0 0 20px rgba(180,80,70,.35);margin-bottom:6px}
.boss-track{height:12px;position:relative;background:rgba(5,8,11,.86);border:1px solid rgba(216,183,116,.38);box-shadow:0 0 0 1px #000,0 0 22px rgba(0,0,0,.6);border-radius:2px;overflow:hidden}
.boss-track i{position:absolute;left:0;top:0;bottom:0;width:100%;background:linear-gradient(180deg,#e08a76,#b13d45 55%,#5c1d26);transition:width .18s}
.boss-segs{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 24%,rgba(0,0,0,.4) 24% 24.4%)}
#bossPhase{font-size:9px;letter-spacing:.26em;color:#b3a17c;margin-top:5px;text-transform:uppercase;text-shadow:0 1px 3px #000}
#bossbar.enraged #bossPhase{color:#e6a07f;animation:pulseTxt 1.2s infinite}
@keyframes pulseTxt{50%{opacity:.55}}

#toasts{position:absolute;left:50%;bottom:calc(92px + var(--safe-b));transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:5px;width:min(500px,90vw)}
.toast{font-size:12px;letter-spacing:.06em;color:#e6e0cf;background:rgba(6,11,15,.82);border:1px solid rgba(216,183,116,.22);border-left:2px solid var(--gold);
  padding:5px 14px;border-radius:2px;animation:toastIn .25s ease,toastOut .4s ease 2.6s forwards;text-shadow:0 1px 3px #000;backdrop-filter:blur(3px);white-space:nowrap;max-width:92vw;overflow:hidden;text-overflow:ellipsis}
.toast.loot{border-left-color:var(--rarity,var(--gold))}
.toast.good{border-left-color:var(--teal)}
.toast.bad{border-left-color:#b13d45}
@keyframes toastIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(-6px)}}

#interactPrompt{position:absolute;left:50%;top:63%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;
  background:rgba(6,11,14,.8);border:1px solid rgba(216,183,116,.3);padding:6px 14px;border-radius:20px;
  font-size:12px;letter-spacing:.08em;color:#e9e2d1;box-shadow:0 4px 20px rgba(0,0,0,.5);backdrop-filter:blur(3px)}
#interactPrompt kbd{font-size:11px}
#perfStats{position:absolute;right:16px;bottom:14px;font-size:10px;color:#7e8d90;letter-spacing:.06em;font-family:monospace;opacity:.65}

/* ------- region banner ------- */
#regionBanner{position:absolute;left:50%;top:32%;transform:translate(-50%,-50%);text-align:center;opacity:0;z-index:25;pointer-events:none;
  transition:opacity 1s ease;text-shadow:0 3px 16px #000}
#regionBanner.on{opacity:1}
.rb-small{font-size:9px;letter-spacing:.5em;color:var(--gold);margin-bottom:10px;text-transform:uppercase}
#regionName{font-family:var(--serif);font-size:clamp(30px,4.4vw,54px);letter-spacing:.15em;color:#f3e9d2;text-transform:uppercase;line-height:1.1}
#regionSub{font-family:var(--serif);font-style:italic;font-size:clamp(12px,1.3vw,16px);color:#c9c0ab;margin-top:7px;letter-spacing:.05em}
.rb-rule{width:min(340px,60vw);height:1px;margin:13px auto;background:linear-gradient(90deg,transparent,rgba(216,183,116,.7),transparent)}

/* ------- dialogue ------- */
#dialogueWrap{position:absolute;inset:0;z-index:40;display:flex;align-items:flex-end;justify-content:center;padding:0 5vw 5vh;
  background:linear-gradient(180deg,transparent 55%,rgba(2,5,8,.55) 100%)}
#dialogueBox{width:min(880px,94vw);display:flex;gap:18px;padding:18px 22px;position:relative;
  background:linear-gradient(180deg,rgba(12,18,24,.97),rgba(7,11,15,.98));
  border:1px solid rgba(216,183,116,.34);border-top-color:rgba(216,183,116,.55);
  box-shadow:0 18px 60px rgba(0,0,0,.7),inset 0 0 40px rgba(0,0,0,.5);border-radius:4px;animation:dlgIn .25s ease}
@keyframes dlgIn{from{opacity:0;transform:translateY(14px)}}
#dialogueBox::before,#dialogueBox::after{content:"";position:absolute;width:12px;height:12px;border:1px solid var(--gold);opacity:.8}
#dialogueBox::before{left:5px;top:5px;border-right:0;border-bottom:0}
#dialogueBox::after{right:5px;bottom:5px;border-left:0;border-top:0}
#dlgPortrait{width:76px;height:88px;flex:0 0 auto;border:1px solid rgba(216,183,116,.25);background:#0a1014;border-radius:2px;overflow:hidden;position:relative}
#dlgPortrait canvas{width:100%;height:100%;display:block;image-rendering:pixelated}
#dlgMain{flex:1;min-width:0}
#dlgName{font-family:var(--serif);font-size:17px;letter-spacing:.13em;color:var(--gold-2);text-transform:uppercase;margin-bottom:6px}
#dlgText{font-family:var(--serif);font-size:16.5px;line-height:1.55;color:#ded9cb;min-height:52px}
#dlgText em{color:var(--teal);font-style:normal}
#dlgChoices{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
#dlgChoices button{font-size:12px;letter-spacing:.05em;padding:7px 14px;border:1px solid rgba(216,183,116,.3);color:#e9e1ce;background:rgba(216,183,116,.05);border-radius:2px;transition:.15s;text-align:left}
#dlgChoices button:hover,#dlgChoices button.sel{background:rgba(216,183,116,.16);border-color:rgba(216,183,116,.65);color:#fff5df}
#dlgHint{position:absolute;right:18px;bottom:10px;font-size:9.5px;letter-spacing:.14em;color:#7f8d90}

