    rect(x, cx + 1, foot - 9, 3, 8, P.tunicLight);
    rect(x, cx - 4, foot - 2, 3, 2, P.boots);
    rect(x, cx + 1, foot - 2, 3, 2, P.boots);
  } else {
    trap(x, cx, topY + 20, topY, 9, 16, 20 + (foot - topY - 20), P.tunic);
