    const w = 4.5 + j * 0.25;
    x.fillRect(Math.round(cx - w), Math.round(topY + 13 + j), Math.round(w * 2), 1);
  }
  // torso
  rect(x, cx - 5, topY + 11, 10, 12, P.tunic);

