/* ============================================================
   ECHOES OF THE FALLEN — boot, main loop and input
   ============================================================ */
import { Game } from './game.js';
import { audio } from './audio.js';

const canvas = document.getElementById('game');
const app = document.getElementById('app');
const loading = document.getElementById('loading');
const loadFill = document.getElementById('loadFill');
const loadText = document.getElementById('loadText');
const rotateHint = document.getElementById('rotateHint');

let game = null;
let last = 0;
let started = false;

const wait = ms => new Promise(r => setTimeout(r, ms));
const frameWait = () => new Promise(r => requestAnimationFrame(() => r()));

function setLoad(pct, text) {
  if (loadFill) loadFill.style.width = Math.round(pct) + '%';
  if (loadText) loadText.textContent = text;
}

function updateLoadingLabel() {
  if (!game) return;
  if (loadText) loadText.textContent = 'The echo answers.';
}

async function boot() {
  setLoad(6, 'Opening the archive…');
  await frameWait();
  setLoad(18, 'Kindling the hearth…');
  await wait(80);
  setLoad(34, 'Raising the five regions…');
  await frameWait();

  try {
    game = new Game(canvas);
  } catch (err) {
    console.error('ECHOES boot failed', err);
    if (loadText) loadText.textContent = 'The echo could not be reached — see console.';
    if (loadFill) loadFill.style.background = '#b13d45';
    return;
  }

  // Exposed for debugging and for the project's browser capture workflow.
  window.game = game;
  window.__ECHO__ = game;

  setLoad(58, 'Waking the old roads…');
  await wait(120);
  setLoad(76, 'Teaching the guardians to remember…');
  await frameWait();
  setLoad(92, 'Tuning the echo…');
  await wait(160);
  setLoad(100, 'The echo answers.');
  await wait(240);

  if (loading) loading.classList.add('gone');
  updateTitleMenu();
  checkOrientation();

  bindInput();
  started = true;
  last = performance.now();
  requestAnimationFrame(loop);
}

function updateTitleMenu() {
  if (!game) return;
  game.ui.updateTitle();
}

function loop(now) {
  if (!started) return;
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;
  try {
    game.update(dt);
    game.renderer.render(dt);
  } catch (err) {
    console.error('ECHOES frame error', err);
    started = false;
    if (loadText) {
      if (loading) loading.classList.remove('gone');
      loadText.textContent = 'A seam opened in the world — see console.';
    }
    return;
  }
  requestAnimationFrame(loop);
}

/* ---------------- input ---------------- */
function blockKeys(e) {
  const k = e.key.toLowerCase();
  return [' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright', 'tab'].includes(k);
}

function bindInput() {
  if (!game) return;

  window.addEventListener('keydown', e => {
    if (!game) return;
    const tag = (e.target && e.target.tagName) || '';
    if (tag === 'INPUT' || tag === 'TEXTAREA') {
      if (e.key === 'Escape') { game.ui.closeAll(); e.preventDefault(); }
      return;
    }
    // Title panels are outside the in-game key router.
    if (game.state === 'title' && game.ui.panelOpen) {
      if (e.key === 'Escape' || e.key.toLowerCase() === 'p') {
        game.ui.closeAll();
        e.preventDefault();
        return;
      }
      if (e.key === 'Tab') { e.preventDefault(); return; }
    }
    if (blockKeys(e) && game.state !== 'title') e.preventDefault();
    game.onKeyDown(e);
  }, { passive: false });

  window.addEventListener('keyup', e => {
    if (game) game.onKeyUp(e);
  });

  canvas.addEventListener('mousemove', e => {
    if (game) game.onMouseMove(e.clientX, e.clientY);
  });

  canvas.addEventListener('mousedown', e => {
    if (!game) return;
    if (e.button === 0 || e.button === 2) {
      e.preventDefault();
      if (game.state === 'playing') game.onMouseDown(e.button);
    }
  });

  canvas.addEventListener('contextmenu', e => e.preventDefault());
  app.addEventListener('contextmenu', e => e.preventDefault());

  let resizeTimer = null;
  const onResize = () => {
    if (!game) return;
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      game.resize();
      checkOrientation();
    }, 60);
  };
  window.addEventListener('resize', onResize);
  window.addEventListener('orientationchange', () => setTimeout(onResize, 220));

  window.addEventListener('blur', () => {
    if (!game) return;
    game.keys.clear();
    game.input.joyActive = false;
  });
  document.addEventListener('visibilitychange', () => {
    if (!game) return;
    if (document.hidden) {
      game.keys.clear();
      game.input.joyActive = false;
      game.save(true);
    } else {
      last = performance.now();
    }
  });

  // Browsers require a gesture before audio may begin.
  const wake = () => {
    audio.init();
    if (game) game.audio.setVolumes(game.settings.music, game.settings.sfx, game.settings.muted);
    window.removeEventListener('pointerdown', wake);
    window.removeEventListener('keydown', wake);
  };
  window.addEventListener('pointerdown', wake);
  window.addEventListener('keydown', wake);
}

function checkOrientation() {
  if (!rotateHint || !game) return;
  const portrait = window.innerHeight > window.innerWidth && window.innerWidth < 760;
  const show = portrait && game.state === 'playing' && game.ui && game.ui.touchEnabled;
  rotateHint.classList.toggle('hidden', !show);
}

window.addEventListener('error', e => {
  console.error('ECHOES runtime error', e.error || e.message);
});

boot();

/* ============================================================
   ECHOES OF THE FALLEN — additional interface surfaces
   ============================================================ */
.ab-slot{pointer-events:auto;cursor:pointer}
.slots.scroll{flex:1;min-height:0;overflow-y:auto}
.slot .es-empty{color:#62706c;font-size:13px}
.slot .rarity-bar{display:block}
#objective.pulse{animation:objPulse .55s ease}
@keyframes objPulse{40%{box-shadow:0 0 26px rgba(216,183,116,.22);border-right-color:rgba(240,217,164,.95)}}

.levelup-banner{position:absolute;left:50%;top:24%;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;
  gap:1px;z-index:24;pointer-events:none;animation:lvlIn 2.3s ease forwards;text-shadow:0 3px 18px #000}
.levelup-banner span{font-size:9px;letter-spacing:.55em;color:var(--gold);text-transform:uppercase}
.levelup-banner b{font-family:var(--serif);font-size:58px;font-weight:400;line-height:1;color:#fff0c5;
  text-shadow:0 0 40px rgba(255,222,150,.55),0 4px 18px #000}
.levelup-banner i{font-style:normal;font-size:9px;letter-spacing:.26em;color:#cdbf9d;text-transform:uppercase}
@keyframes lvlIn{0%{opacity:0;transform:translate(-50%,-46%) scale(.92)}18%{opacity:1;transform:translate(-50%,-50%) scale(1)}
  72%{opacity:1;transform:translate(-50%,-50%) scale(1)}100%{opacity:0;transform:translate(-50%,-56%) scale(1.02)}}

/* --- inventory / character additions --- */
.inv-toolbar .cap{white-space:nowrap}
.pal-dot.locked{opacity:.26;position:relative}
.pal-dot.locked::after{content:"";position:absolute;inset:-2px;border-radius:50%;border:1px dashed rgba(216,183,116,.4)}
.acc-row{max-width:240px}
.acc-row .btn{padding:5px 9px;font-size:9px;letter-spacing:.08em}
.btn.is-locked{opacity:.38}
.pal-note{font-size:10px;line-height:1.55;color:#7e8b86;font-style:italic;margin-top:18px;max-width:460px}

/* --- quests --- */
.qd-obj.current .box{border-color:var(--gold);box-shadow:0 0 8px rgba(216,183,116,.25)}
.qd-obj.current span:last-child{color:#f2ead6}
.quest-track{display:flex;justify-content:flex-end}
.quest-item.on .qg{color:var(--gold-2)}

/* --- map --- */
.map-note{display:flex;gap:7px;align-items:flex-start;font-size:10px;line-height:1.5;color:#c8c0ac;border-top:1px solid rgba(216,183,116,.13);padding-top:10px}
.map-note .diamond{margin-top:3px;flex:0 0 auto}
.map-wrap canvas{max-width:96%;max-height:94%}

/* --- controls --- */
.ctrl-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 20px}
.ctrl-grid > div{display:flex;gap:10px;align-items:center;font-size:11px;color:#aeb8b0;padding:6px 0;border-bottom:1px dotted rgba(255,255,255,.06)}
.ctrl-grid kbd{min-width:66px;text-align:center;font-size:9px;letter-spacing:.04em}
.ability-help{display:flex;flex-direction:column;gap:5px}
.ah-row{display:flex;gap:12px;align-items:flex-start;padding:8px 10px;border:1px solid rgba(216,183,116,.12);border-radius:2px;background:rgba(0,0,0,.14)}
.ah-key{width:20px;height:20px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;border:1px solid rgba(216,183,116,.32);border-radius:2px;font-size:10px;color:var(--gold-2)}
.ah-row b{display:block;font-family:var(--serif);font-size:12px;font-weight:400;color:#e9e2cf}
.ah-row div span{display:block;font-size:9.5px;line-height:1.4;color:#87948f;margin-top:1px}
.ah-cost{margin-left:auto;font-size:8.5px;letter-spacing:.08em;color:#7fa9b0;white-space:nowrap}

/* --- shop --- */
.shop-layout{display:flex;flex:1;min-height:0;width:100%}
.shop-left,.shop-right{flex:1;min-width:0;display:flex;flex-direction:column;padding:16px 18px;gap:9px}
.shop-right{border-left:1px solid rgba(216,183,116,.14);background:rgba(0,0,0,.1)}
.shop-list{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px;padding-right:4px}
.shop-item{display:flex;gap:10px;align-items:flex-start;padding:9px;border:1px solid rgba(216,183,116,.13);border-radius:3px;background:rgba(255,255,255,.015)}
.shop-item:hover{border-color:rgba(216,183,116,.3);background:rgba(216,183,116,.035)}
.shop-ic{width:42px;height:42px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;border:1px solid rgba(216,183,116,.14);border-radius:2px;background:rgba(0,0,0,.25)}
.shop-ic img{width:86%;height:86%;object-fit:contain;image-rendering:pixelated}
.shop-info{flex:1;min-width:0}
.shop-name{font-family:var(--serif);font-size:13px;line-height:1.25}
.shop-sub{font-size:8px;letter-spacing:.13em;text-transform:uppercase;color:#78858a;margin-top:1px}
.shop-desc{font-size:9.5px;line-height:1.35;color:#89958f;margin-top:3px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.shop-item .btn{align-self:center;padding:6px 10px;font-size:9px;letter-spacing:.06em;min-width:64px}
.shop-item.compact{padding:7px 8px}
.shop-item.compact .shop-ic{width:32px;height:32px}
.shop-item.compact .shop-name{font-size:11.5px}

/* --- forge --- */
.forge-layout{flex:1;padding:18px 24px;overflow-y:auto}
.forge-note{font-family:var(--serif);font-style:italic;font-size:12.5px;line-height:1.6;color:#a19f8f;max-width:760px;margin-bottom:18px;border-left:2px solid rgba(216,183,116,.25);padding-left:12px}
.forge-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:18px}
.forge-slot{border:1px solid rgba(216,183,116,.16);border-radius:3px;padding:12px;background:rgba(0,0,0,.16);display:flex;flex-direction:column;gap:8px;min-width:0}
.forge-slot.empty{opacity:.55}
.forge-slot .id-head{margin-bottom:0}
.forge-slot .btn{margin-top:auto;font-size:9.5px;padding:8px 7px;letter-spacing:.05em}
.forge-slot .id-stat{font-size:10.5px}
.forge-slot h3{font-family:var(--serif);font-size:14px;font-weight:400;line-height:1.2}

/* --- lore --- */
.lore-panel{width:min(720px,94vw);height:auto;max-height:82vh}
.lore-body{padding:24px 34px 28px;display:flex;flex-direction:column;align-items:flex-start;gap:12px}
.lore-mark{font-size:18px;color:var(--gold);text-shadow:0 0 18px rgba(216,183,116,.5)}
.lore-body p{font-family:var(--serif);font-size:15.5px;line-height:1.75;color:#d8d3c4;max-width:620px;white-space:pre-wrap}
.lore-body p:first-of-type::first-letter{font-size:2.1em;line-height:.8;color:var(--gold-2);float:left;padding:5px 8px 0 0}
.lore-rule{width:120px;height:1px;background:linear-gradient(90deg,rgba(216,183,116,.7),transparent);margin:8px 0}
.lore-body .btn{align-self:flex-end}

/* --- pause / death / ending --- */
.pause-kicker{font-size:8.5px;letter-spacing:.5em;color:#8b7a56;text-transform:uppercase;margin-bottom:8px}
.death-panel{width:min(560px,94vw);height:auto;padding:34px 30px 28px;text-align:center;
  background:radial-gradient(ellipse at 50% 18%,rgba(120,40,44,.16),transparent 60%),linear-gradient(165deg,rgba(14,20,27,.99),rgba(7,10,14,.995))}
.death-mark{font-size:30px;color:#c25a5a;text-shadow:0 0 26px rgba(190,60,70,.6);margin-bottom:10px}
.death-kicker{font-size:8px;letter-spacing:.46em;color:#a87979;text-transform:uppercase;margin-bottom:8px}
.death-panel h2{font-family:var(--serif);font-size:34px;font-weight:400;letter-spacing:.18em;color:#e6cece;line-height:1.05}
.death-sub{font-family:var(--serif);font-style:italic;font-size:14px;color:#a99a97;margin:12px 0 6px}
.death-meta{font-size:10.5px;letter-spacing:.1em;color:#8f7777;margin-bottom:22px}
.ending-panel{width:min(760px,94vw);height:min(780px,92vh);padding:26px 42px 24px;text-align:center;display:flex;flex-direction:column;align-items:center;
  background:radial-gradient(ellipse at 50% 18%,rgba(111,217,200,.1),transparent 55%),radial-gradient(ellipse at 50% 100%,rgba(216,183,116,.07),transparent 55%),linear-gradient(165deg,rgba(13,20,25,.99),rgba(6,9,12,.995))}
.ending-rules{width:min(260px,60vw);height:1px;background:linear-gradient(90deg,transparent,rgba(216,183,116,.7),transparent);margin:0 0 18px}
.ending-kicker{font-size:8px;letter-spacing:.52em;color:var(--gold);text-transform:uppercase;margin-bottom:10px}
.ending-panel h2{font-family:var(--serif);font-size:clamp(30px,4vw,46px);font-weight:400;letter-spacing:.18em;color:#f3ead4;
  text-shadow:0 0 50px rgba(111,217,200,.2),0 4px 22px #000;margin-bottom:16px}
.ending-body{font-family:var(--serif);font-size:14.5px;line-height:1.72;color:#c5c3b4;max-width:590px;text-align:left;max-height:44vh;overflow-y:auto;padding-right:12px}
.ending-body p{margin-bottom:12px}
.ending-final{color:#e4d7b9;font-style:italic;text-align:center;padding:6px 0 2px}
.ending-stats{display:flex;gap:34px;justify-content:center;margin:20px 0}
.ending-stats div{display:flex;flex-direction:column;gap:2px}
.ending-stats span{font-size:8px;letter-spacing:.3em;color:#7f8b84}
.ending-stats b{font-family:var(--serif);font-size:22px;font-weight:400;color:var(--gold-2)}

/* --- touch extras --- */
.tbtn.ab .ab-key{font-family:var(--serif);font-size:calc(13px * var(--tscale));color:#d8e8e4;line-height:1}
.tbtn.ab[data-ability=echo]{left:calc(76px * var(--tscale));top:calc(-30px * var(--tscale))}
.tbtn[data-act=heavy]{right:calc(20px * var(--tscale));bottom:calc(150px * var(--tscale));width:calc(46px * var(--tscale));height:calc(46px * var(--tscale));font-size:calc(13px * var(--tscale))}
.tbtn[data-act=block]{right:calc(88px * var(--tscale));bottom:calc(116px * var(--tscale));width:calc(44px * var(--tscale));height:calc(44px * var(--tscale));font-size:calc(13px * var(--tscale))}
#dlgChoices.nudge{animation:choiceNudge .35s ease}
@keyframes choiceNudge{25%{transform:translateX(-4px)}75%{transform:translateX(4px)}}

@media (max-width:900px){
  .shop-left,.shop-right{padding:12px}
  .forge-grid{grid-template-columns:1fr}
  .ctrl-grid{grid-template-columns:1fr}
  .ending-panel{padding:20px 22px}
  .ending-stats{gap:22px}
}
@media (max-width:640px){
  .inv-right{max-height:42%}
  .shop-layout{flex-direction:column}
  .shop-left,.shop-right{flex:1;min-height:0}
  .shop-right{border-left:0;border-top:1px solid rgba(216,183,116,.14)}
  .lore-body{padding:18px}
  .lore-body p{font-size:14px}
  .death-panel{padding:24px 18px}
  .death-panel h2{font-size:26px}
  .ending-body{font-size:13px;max-height:38vh}
  .ending-stats{gap:16px}
  .ending-stats b{font-size:18px}
  .ah-row{padding:6px}
  .levelup-banner b{font-size:44px}
}

